def count_substrings(s):
    count = 0
    prefix_sum = 0
    prefix_map = {0: 1}

    for i, char in enumerate(s):
        digit = int(char)
        prefix_sum += digit

        target = prefix_sum - (i + 1)

        if target in prefix_map:
            count += prefix_map[target]

        prefix_map[prefix_sum] = prefix_map.get(prefix_sum, 0) + 1

